"use client"

// Bollard UI — address-check · MIT licence · https://bollard-ui.vercel.app/components/address-check

import * as React from "react"
import { CircleAlert, LoaderCircle, MapPinOff, PackageX, RotateCw, Tag } from "lucide-react"

import { cn } from "@/lib/utils"
import {
  COUNTRIES,
  checkPostcode,
  findAddressIssues,
  formatLabel,
  type Address,
  type AddressField,
  type AddressIssue,
  type PostcodePlace,
} from "./address-rules"

export * from "./address-rules"

const fill = (template: string, values: Record<string, string>) => template.replace(/\{(\w+)\}/g, (m, k: string) => values[k] ?? m)

const fieldClass =
  "h-9 w-full min-w-0 rounded-md border bg-transparent px-3 text-base shadow-xs transition-[color,box-shadow] outline-none placeholder:text-muted-foreground focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 md:text-sm dark:bg-input/30 data-warning:border-amber-500 dark:data-warning:border-amber-400"
const fixClass =
  "inline-flex h-6 items-center gap-1 rounded-md border border-amber-500/40 px-2 font-medium text-amber-900 transition-colors hover:bg-amber-500/10 dark:text-amber-200 outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50"
const EMPTY: Address = { country: "IN", line1: "", line2: "", city: "", region: "", postcode: "" }

export interface AddressCheckProps extends Omit<React.ComponentProps<"fieldset">, "defaultValue" | "onChange"> {
  /** Controlled address. */
  value?: Address
  /** Initial address when uncontrolled. */
  defaultValue?: Partial<Address>
  /** Called with the whole address on every change. */
  onValueChange?: (value: Address) => void
  /** Looks up where a postcode is. Resolve null when no result is returned, undefined when it can't be checked. */
  lookupPostcode?: (country: string, postcode: string, signal: AbortSignal) => Promise<PostcodePlace | null | undefined>
  /** Message when the postcode lookup returns no place. */
  postcodeLookupEmptyMessage?: string
  /** Message when no local lookup data is available. */
  postcodeLookupUnknownMessage?: string
  /** Message when the lookup fails. */
  postcodeLookupFailedMessage?: string
  /** Retry button label after a lookup failure. */
  postcodeLookupRetryLabel?: string
  /** Country codes offered in the picker, from the built-in rules. */
  countries?: string[]
  /** Labels and placeholders. */
  line1Label?: string
  /** Placeholder for the first address line. */
  line1Placeholder?: string
  /** Label for the second address line. */
  line2Label?: string
  /** Placeholder for the second address line. */
  line2Placeholder?: string
  /** Label for the city field. */
  cityLabel?: string
  /** Heading above the printed-label readback. */
  labelHeading?: string
  /** Messages. `{city}`, `{typed}`, `{postcode}`, `{label}`, `{example}`, `{country}` are filled in. */
  noNumberMessage?: string
  /** Text for dismissing the missing-number warning. */
  noNumberDismissLabel?: string
  /** Warning for PO box addresses. */
  poBoxMessage?: string
  /** Message offering the corrected postcode. */
  postcodeFixMessage?: string
  /** Message when the postcode fits another country. */
  otherCountryMessage?: string
  /** Message when the postcode doesn't fit the country. */
  invalidPostcodeMessage?: string
  /** Message when the city doesn't match the postcode. */
  cityMismatchMessage?: string
  /** Message when the city is empty but the postcode is known. */
  cityMissingMessage?: string
}

/**
 * A postal address block that catches what makes parcels come back: no house
 * or flat number, a postcode that doesn't fit the country (or fits another one),
 * a city that the postcode lookup says is elsewhere, and PO boxes couriers can't
 * reach. It prints a live label of exactly what the courier will see, with the
 * weak spots marked, and every fix is one tap, never automatic.
 */
export function AddressCheck({
  value,
  defaultValue,
  onValueChange,
  lookupPostcode,
  countries = Object.keys(COUNTRIES),
  line1Label = "Flat / house no., building, street",
  line1Placeholder = "B-204, Sai Residency, Baner Road",
  line2Label = "Area, landmark (optional)",
  line2Placeholder = "Near Balewadi High Street",
  cityLabel = "City",
  labelHeading = "Will print as",
  noNumberMessage = "No flat or house number. Couriers may not find the door.",
  noNumberDismissLabel = "It has none",
  poBoxMessage = "Couriers can't deliver to a PO box. Use a street address.",
  postcodeFixMessage = "{label} should be written {fixed}.",
  otherCountryMessage = "That looks like a {country} postcode.",
  invalidPostcodeMessage = "{label} should be {example}.",
  cityMismatchMessage = "{postcode} is in {city}, not {typed}.",
  cityMissingMessage = "{postcode} is in {city}.",
  postcodeLookupEmptyMessage = "No area details were returned for this postcode.",
  postcodeLookupUnknownMessage = "This postcode wasn't checked by a directory.",
  postcodeLookupFailedMessage = "Couldn't look up this postcode.",
  postcodeLookupRetryLabel = "Retry",
  className,
  ...props
}: AddressCheckProps) {
  const [inner, setInner] = React.useState<Address>({ ...EMPTY, ...defaultValue })
  const [focused, setFocused] = React.useState<keyof Address>()
  const [noNumberOk, setNoNumberOk] = React.useState(false)
  const [places, setPlaces] = React.useState<Record<string, PostcodePlace | null | undefined>>({})
  const [lookupErrors, setLookupErrors] = React.useState<Record<string, true>>({})
  const [loading, setLoading] = React.useState(false)
  const [attempt, setAttempt] = React.useState(0)
  const lookupRef = React.useRef(lookupPostcode)
  React.useEffect(() => { lookupRef.current = lookupPostcode }, [lookupPostcode])
  const rootRef = React.useRef<HTMLFieldSetElement>(null)
  const id = React.useId()
  const address = value ?? inner
  const rule = COUNTRIES[address.country]
  const key = `${address.country}:${address.postcode.trim()}`
  const postcodeOk = checkPostcode(address.country, address.postcode).status === "ok"

  React.useEffect(() => {
    const lookup = lookupRef.current
    if (!lookup || !postcodeOk || key in places) return
    const controller = new AbortController()
    const timer = setTimeout(() => {
      setLoading(true)
      Promise.resolve()
        .then(() => controller.signal.aborted ? undefined : lookup(address.country, address.postcode.trim(), controller.signal))
        .then((place) => {
          if (controller.signal.aborted) return
          setPlaces((all) => ({ ...all, [key]: place }))
        })
        .catch(() => {
          if (!controller.signal.aborted) setLookupErrors((all) => ({ ...all, [key]: true }))
        })
        .finally(() => !controller.signal.aborted && setLoading(false))
    }, 300)
    return () => {
      clearTimeout(timer)
      controller.abort()
      setLoading(false)
    }
  }, [key, postcodeOk, Boolean(lookupPostcode), places, address.country, address.postcode, attempt])

  const update = (patch: Partial<Address>) => {
    const next = { ...address, ...patch }
    if (value === undefined) setInner(next)
    onValueChange?.(next)
  }

  /** Applies a one-tap fix and flashes the field and label line it changed. */
  const apply = (patch: Partial<Address>) => {
    update(patch)
    requestAnimationFrame(() => {
      if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return
      for (const field of Object.keys(patch)) {
        rootRef.current?.querySelectorAll(`[data-flash~="${field}"]`).forEach((el) =>
          el.animate([{ backgroundColor: "rgb(245 158 11 / 0.3)" }, { backgroundColor: "transparent" }], { duration: 400, easing: "ease-out" }),
        )
      }
    })
  }

  const place = postcodeOk ? places[key] : undefined
  const issues = findAddressIssues(address, place).filter((issue) => !(issue.kind === "no-number" && noNumberOk))
  const visible = (field: AddressField) =>
    issues.filter((issue) => issue.field === field && (issue.kind === "po-box" || focused !== field) && !(issue.kind === "no-number" && focused === "line2"))
  const values = (extra: Record<string, string> = {}) => ({
    postcode: address.postcode.trim(), typed: address.city.trim(), label: rule?.postcodeLabel ?? "postcode", example: rule?.example ?? "", ...extra,
  })

  const message = (issue: AddressIssue): [React.ReactNode, React.ReactNode?] => {
    if (issue.kind === "po-box") return [poBoxMessage]
    if (issue.kind === "no-number") return [noNumberMessage, <button type="button" className={fixClass} onClick={() => setNoNumberOk(true)}>{noNumberDismissLabel}</button>]
    if (issue.kind === "city") {
      const { city, region } = issue.place
      const patch = { city, ...(region && region !== address.region ? { region } : {}) }
      return [fill(address.city.trim() ? cityMismatchMessage : cityMissingMessage, values({ city })), <button type="button" className={fixClass} onClick={() => apply(patch)}>Use {city}</button>]
    }
    const { check } = issue
    if (check.status === "fixable") return [fill(postcodeFixMessage, values({ fixed: check.fixed })), <button type="button" className={fixClass} onClick={() => apply({ postcode: check.fixed })}>Use {check.fixed}</button>]
    if (check.status === "other-country") {
      const other = COUNTRIES[check.country]
      const fixed = other.normalize ? other.normalize(address.postcode) : address.postcode
      return [fill(otherCountryMessage, values({ country: other.name })), <button type="button" className={fixClass} onClick={() => apply({ country: check.country, postcode: fixed })}>Switch to {other.name}</button>]
    }
    return [fill(invalidPostcodeMessage, values())]
  }

  const warnings = (field: AddressField) => (
    <div id={`${id}-${field}-hint`} aria-live="polite" className="text-xs empty:hidden">
      {visible(field).map((issue) => {
        const [text, fix] = message(issue)
        const Icon = issue.kind === "po-box" ? PackageX : MapPinOff
        return (
          <p key={issue.kind} className="flex gap-1.5 text-amber-700 motion-safe:animate-[cui-address-check-in_200ms_ease-out] dark:text-amber-400">
            <span className="flex h-6 shrink-0 items-center"><Icon aria-hidden className="size-3.5" /></span>
            <span className="flex min-w-0 flex-wrap items-center gap-x-2"><span className="py-1">{text}</span>{fix}</span>
          </p>
        )
      })}
    </div>
  )

  const input = (field: AddressField, label: string, extra: React.ComponentProps<"input"> = {}) => (
    <div className="grid min-w-0 content-start gap-1.5">
      <label htmlFor={`${id}-${field}`} className="w-fit text-sm font-medium">{label}</label>
      <input
        id={`${id}-${field}`}
        value={address[field]}
        onChange={(e) => update({ [field]: e.target.value })}
        onFocus={() => setFocused(field)}
        onBlur={() => setFocused(undefined)}
        aria-describedby={field === "postcode" && rule?.postcodeLabel !== null ? `${id}-${field}-hint ${id}-postcode-lookup` : `${id}-${field}-hint`}
        data-warning={visible(field).length ? "" : undefined}
        data-flash={field}
        className={fieldClass}
        {...extra}
      />
      {field !== "city" && field !== "postcode" && warnings(field)}
    </div>
  )

  const label = formatLabel(address)
  const flagged = new Set<string>(issues.filter((issue) => issue.kind !== "no-number").map((issue) => issue.field))

  return (
    <fieldset ref={rootRef} data-slot="address-check" className={cn("grid w-full max-w-sm min-w-0 gap-3", className)} {...props}>
      <style>{"@keyframes cui-address-check-in{from{opacity:0;transform:translateY(-3px)}}"}</style>
      <div className="grid gap-1.5">
        <label htmlFor={`${id}-country`} className="w-fit text-sm font-medium">Country</label>
        <select id={`${id}-country`} value={address.country} onChange={(e) => update({ country: e.target.value })} data-flash="country" className={cn(fieldClass, "bg-background pr-8")}>
          {countries.map((code) => <option key={code} value={code}>{COUNTRIES[code]?.name ?? code}</option>)}
        </select>
      </div>
      {input("line1", line1Label, { placeholder: line1Placeholder, autoComplete: "address-line1" })}
      {input("line2", line2Label, { placeholder: line2Placeholder, autoComplete: "address-line2" })}
      <div className="grid grid-cols-2 gap-3">
        {input("city", cityLabel, { autoComplete: "address-level2" })}
        {input("region", rule?.regionLabel ?? "Region", { autoComplete: "address-level1" })}
        {rule?.postcodeLabel !== null && (
          <div className="relative">
            {input("postcode", rule?.postcodeLabel ?? "Postcode", { autoComplete: "postal-code", autoCapitalize: "characters", spellCheck: false })}
            {loading && <LoaderCircle aria-label="Checking postcode" className="absolute right-2.5 bottom-2.5 size-4 animate-spin text-muted-foreground" />}
          </div>
        )}
      </div>
      {(visible("postcode").length > 0 || visible("city").length > 0) && (
        <div className="-mt-1.5">{warnings("postcode")}{warnings("city")}</div>
      )}
      {rule?.postcodeLabel !== null && (
        <div id={`${id}-postcode-lookup`} aria-live="polite" className="-mt-2 text-xs text-muted-foreground">
          {loading && <p className="flex items-center gap-1.5"><LoaderCircle aria-hidden className="size-3.5 animate-spin" /> Looking up this postcode…</p>}
          {!loading && key in places && places[key] === undefined && <p>{postcodeLookupUnknownMessage}</p>}
          {!loading && key in places && places[key] === null && <p>{postcodeLookupEmptyMessage}</p>}
          {!loading && lookupErrors[key] && (
            <p className="flex flex-wrap items-center gap-2">
              <span className="inline-flex items-center gap-1.5"><CircleAlert aria-hidden className="size-3.5" />{postcodeLookupFailedMessage}</span>
              <button type="button" onClick={() => { setLookupErrors((all) => { const next = { ...all }; delete next[key]; return next }); setAttempt((n) => n + 1) }} className={fixClass}>
                <RotateCw aria-hidden className="size-3" /> {postcodeLookupRetryLabel}
              </button>
            </p>
          )}
        </div>
      )}
      <figure className="rounded-lg border border-dashed bg-muted/40 p-3">
        <figcaption className="mb-2 flex items-center gap-1.5 text-xs font-medium text-muted-foreground">
          <Tag aria-hidden className="size-3.5" /> {labelHeading}
        </figcaption>
        <address className="grid gap-0.5 font-mono text-xs leading-5 not-italic">
          {label.length < 2 ? <span className="text-muted-foreground">—</span> : label.map((line, index) => (
            <span key={index} data-flash={line.fields.join(" ")} className={cn("w-fit rounded-sm px-1 -mx-1 break-words", line.fields.some((field) => flagged.has(field)) && "underline decoration-amber-500 decoration-wavy underline-offset-4")}>
              {line.fields[0] === "line1" && issues.some((i) => i.kind === "no-number") && (
                <span className="mr-1 rounded-sm bg-amber-500/20 px-1 text-amber-800 dark:text-amber-300">No.?</span>
              )}
              {line.text}
            </span>
          ))}
        </address>
      </figure>
    </fieldset>
  )
}

// Bollard UI — address-check · MIT licence · https://bollard-ui.vercel.app/components/address-check

/** A postal address as the form holds it. `country` is an ISO 3166-1 alpha-2 code. */
export interface Address {
  country: string
  line1: string
  line2: string
  city: string
  region: string
  postcode: string
}

export type AddressField = Exclude<keyof Address, "country">

export interface CountryRule {
  name: string
  /** What the postcode is called there, or null when the country has no postcodes (UAE). */
  postcodeLabel: string | null
  regionLabel: string
  /** Canonical shape, uppercase with the right separator. */
  pattern?: RegExp
  /** Turns "sw1a1aa" into "SW1A 1AA", "4110 39" into "411039", "560O01" into "560001". */
  normalize?: (raw: string) => string
  /** Shape shown in the warning, e.g. "6 digits, like 411001". */
  example?: string
  /** How the city / region / postcode line prints on a label. */
  cityLine: (a: Address) => string[]
}

const compact = (s: string) => s.toUpperCase().replace(/[\s-]+/g, "")
/** O and I typed for 0 and 1 in an all-digit code. */
const digits = (s: string) => compact(s).replace(/O/g, "0").replace(/[IL]/g, "1")
/** Re-inserts the space before the last `n` characters. */
const split = (n: number) => (s: string) => {
  const c = compact(s)
  return c.length > n ? `${c.slice(0, -n)} ${c.slice(-n)}` : c
}
const join = (...parts: string[]) => parts.filter(Boolean).join(" ")

export const COUNTRIES: Record<string, CountryRule> = {
  IN: { name: "India", postcodeLabel: "PIN code", regionLabel: "State", pattern: /^[1-9]\d{5}$/, normalize: digits, example: "6 digits, like 411001",
    cityLine: (a) => [join(a.city, a.postcode && `- ${a.postcode}`), a.region] },
  US: { name: "United States", postcodeLabel: "ZIP code", regionLabel: "State", pattern: /^\d{5}(-\d{4})?$/, example: "5 digits, like 94103",
    normalize: (s) => { const d = digits(s); return d.length === 9 ? `${d.slice(0, 5)}-${d.slice(5)}` : d },
    cityLine: (a) => [join(a.city && `${a.city},`, a.region, a.postcode)] },
  GB: { name: "United Kingdom", postcodeLabel: "Postcode", regionLabel: "County", pattern: /^(GIR 0AA|[A-PR-UWYZ][A-HK-Y]?\d[A-Z\d]? \d[ABD-HJLNP-UW-Z]{2})$/, normalize: split(3), example: "like SW1A 1AA",
    cityLine: (a) => [a.city.toUpperCase(), a.region, a.postcode] },
  CA: { name: "Canada", postcodeLabel: "Postal code", regionLabel: "Province", pattern: /^[ABCEGHJ-NPRSTVXY]\d[A-Z] \d[A-Z]\d$/, normalize: split(3), example: "like K1A 0B1",
    cityLine: (a) => [join(a.city, a.region, a.postcode && ` ${a.postcode}`)] },
  AU: { name: "Australia", postcodeLabel: "Postcode", regionLabel: "State", pattern: /^\d{4}$/, normalize: digits, example: "4 digits, like 2000",
    cityLine: (a) => [join(a.city.toUpperCase(), a.region, a.postcode)] },
  DE: { name: "Germany", postcodeLabel: "Postleitzahl", regionLabel: "State", pattern: /^\d{5}$/, normalize: digits, example: "5 digits, like 10115",
    cityLine: (a) => [join(a.postcode, a.city)] },
  NL: { name: "Netherlands", postcodeLabel: "Postcode", regionLabel: "Province", pattern: /^[1-9]\d{3} [A-RT-Z][A-Z]$/, normalize: split(2), example: "like 1012 AB",
    cityLine: (a) => [join(a.postcode, a.city.toUpperCase())] },
  SG: { name: "Singapore", postcodeLabel: "Postal code", regionLabel: "District", pattern: /^\d{6}$/, normalize: digits, example: "6 digits, like 018956",
    cityLine: (a) => [join(a.city || "Singapore", a.postcode)] },
  JP: { name: "Japan", postcodeLabel: "Postal code", regionLabel: "Prefecture", pattern: /^\d{3}-\d{4}$/, example: "like 100-0001",
    normalize: (s) => { const d = digits(s); return d.length === 7 ? `${d.slice(0, 3)}-${d.slice(3)}` : d },
    cityLine: (a) => [join(a.postcode && `〒${a.postcode}`), join(a.region, a.city)] },
  AE: { name: "United Arab Emirates", postcodeLabel: null, regionLabel: "Emirate", cityLine: (a) => [join(a.city, a.region)] },
}

/** Matches "PO Box 12", "P.O. Box", "Post Office Box", "GPO Box", "Locked Bag", "Postfach" but not "Box Hill" or "Pobox Lane". */
const PO_BOX = /\b(p\.?\s*o\.?\s*box|post\s*office\s*box|g\.?p\.?o\.?\s*box|po\s*#|locked\s+bag|postfach)(?=[\s\d#.,]|$)/i

export const isPoBox = (text: string) => PO_BOX.test(text)

/** A street address needs a number somewhere: house, flat, plot, unit or building number. */
export const hasPremiseNumber = (a: Address) => /\d/.test(`${a.line1} ${a.line2}`)

export type PostcodeCheck =
  | { status: "ok" | "empty" | "none" }
  | { status: "fixable"; fixed: string }
  | { status: "other-country"; country: string }
  | { status: "invalid" }

/**
 * Checks a postcode against the country's shape. A near miss that only needs
 * case, spacing or an O→0 swap is "fixable"; a code that only fits one other
 * supported country's shape (a UK postcode with Country = India) says which.
 */
export function checkPostcode(country: string, raw: string): PostcodeCheck {
  const rule = COUNTRIES[country]
  if (!rule?.pattern) return { status: "none" }
  const value = raw.trim()
  if (!value) return { status: "empty" }
  if (rule.pattern.test(value)) return { status: "ok" }
  const fixed = rule.normalize ? rule.normalize(value) : value.toUpperCase()
  if (rule.pattern.test(fixed)) return { status: "fixable", fixed }
  // Only letter or dash shapes are distinctive enough to name another country; a 4-digit typo isn't "Australian".
  if (!/[A-Z-]/i.test(value)) return { status: "invalid" }
  const matches = Object.entries(COUNTRIES).filter(
    ([code, other]) => code !== country && other.pattern && other.pattern.test(other.normalize ? other.normalize(value) : value.toUpperCase()),
  )
  return matches.length === 1 ? { status: "other-country", country: matches[0][0] } : { status: "invalid" }
}

/** What a postcode lookup returns: the place the code belongs to. */
export interface PostcodePlace {
  city: string
  /** Other accepted names, e.g. ["Bangalore"] for Bengaluru. */
  aliases?: string[]
  region?: string
}

export type AddressIssue =
  | { field: "line1" | "line2"; kind: "po-box" }
  | { field: "line1"; kind: "no-number" }
  | { field: "postcode"; kind: "postcode"; check: Exclude<PostcodeCheck, { status: "ok" | "empty" | "none" }> }
  | { field: "city"; kind: "city"; place: PostcodePlace }

/** Every problem a courier would hit, in form order. `place` is the lookup result for the current postcode. */
export function findAddressIssues(a: Address, place?: PostcodePlace | null): AddressIssue[] {
  const issues: AddressIssue[] = []
  if (isPoBox(a.line1)) issues.push({ field: "line1", kind: "po-box" })
  else if (isPoBox(a.line2)) issues.push({ field: "line2", kind: "po-box" })
  else if (a.line1.trim() && !hasPremiseNumber(a)) issues.push({ field: "line1", kind: "no-number" })
  const check = checkPostcode(a.country, a.postcode)
  if (check.status === "fixable" || check.status === "other-country" || check.status === "invalid") issues.push({ field: "postcode", kind: "postcode", check })
  if (place && (!a.city.trim() || !sameCity(a.city, [place.city, ...(place.aliases ?? [])]))) issues.push({ field: "city", kind: "city", place })
  return issues
}

const simplify = (s: string) => s.toLowerCase().normalize("NFD").replace(/[^\p{L}]/gu, "")

/** True when the typed city is the looked-up one or one of its aliases (Bengaluru / Bangalore). */
export function sameCity(typed: string, names: string[]) {
  const t = simplify(typed)
  return names.some((name) => {
    const n = simplify(name)
    return !!n && (t === n || (t.length >= 3 && (t.includes(n) || n.includes(t))))
  })
}

/** The lines a courier label would print, in the country's order, ending with the country name in capitals. `fields` says what each line carries. */
export function formatLabel(a: Address): { fields: (keyof Address)[]; text: string }[] {
  const rule = COUNTRIES[a.country]
  const carried = (text: string) =>
    (["city", "region", "postcode"] as const).filter((field) => a[field].trim() && text.toUpperCase().includes(a[field].trim().toUpperCase()))
  const lines = [
    { fields: ["line1"] as (keyof Address)[], text: a.line1.trim() },
    { fields: ["line2"] as (keyof Address)[], text: a.line2.trim() },
    ...(rule?.cityLine(a) ?? [a.city]).map((text) => ({ fields: carried(text) as (keyof Address)[], text: text.trim() })),
    { fields: ["country"] as (keyof Address)[], text: (rule?.name ?? a.country).toUpperCase() },
  ]
  return lines.filter((line) => line.text)
}
